// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));

        // Address that should succeed according to the intended logic
        address depositor = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;

        // Try calling as the depositor
        bool depositorSuccess;
        vm.prank(depositor);
        try c.setL1BlockValues(0, 0, 0, bytes32(0), 0, bytes32(0), 0, 0) {
            depositorSuccess = true;
        } catch {
            depositorSuccess = false;
        }

        // Try calling as the fuzzed caller (which may or may not be depositor)
        bool callerSuccess;
        vm.prank(caller);
        try c.setL1BlockValues(0, 0, 0, bytes32(0), 0, bytes32(0), 0, 0) {
            callerSuccess = true;
        } catch {
            callerSuccess = false;
        }

        if (caller == depositor) {
            // For the depositor: reference contract allows it, mutant reverts
            // The property: depositor must always succeed
            assertTrue(depositorSuccess);
        } else {
            // For non-depositor: both should revert
            // The property: non-depositor must always revert
            assertTrue(!callerSuccess);
        }
    }
}

